// import request from '@/utils/request'

import request from '@/hooks/useHttp'
import mitt from 'mitt'
export const eventBus = mitt()

//检查更新下载状态

export function checkDownloadStatus(params) {
  return request({
    method: 'get',
    url: '/update/check_download_status',
    params
  })
}

//检查更新
export function checkUpdate(data) {
  return request({
    method: 'get',
    url: '/update/check_update',
    data
  })
}

//下载文件
export function startDownload(data) {
  return request({
    method: 'get',
    url: '/update/start_download',
    data,
    timeout: 15 * 60 * 1000
  })
}

//下载文件
export function exitImmediately(data) {
  return request({
    method: 'get',
    url: '/update/exit_immediately',
    data
  })
}

//插入版本
export function versionInsert(data) {
  return request({
    method: 'post',
    url: '/update/version/insert',
    data
  })
}

//获取版本
export function getVersionList(data) {
  return request({
    method: 'get',
    url: '/update/version/list',
    data
  })
}

//更新版本
export function versionUpdate(data) {
  return request({
    method: 'post',
    url: '/update/version/update',
    data
  })
}

//删除版本
export function versionDelete(data) {
  return request({
    method: 'post',
    url: '/update/version/delete',
    data
  })
}
