<script setup>
import { checkUpdate, startDownload, exitImmediately, eventBus } from '@/services/update'
import Button from 'primevue/button'
import Dialog from 'primevue/dialog'
import { ref, onMounted } from 'vue'
import { useToast } from 'primevue/usetoast'

const emits = defineEmits(['close'])
const dialogRef = inject('dialogRef')
const toast = useToast()
const taskId = ref(null)

// 使用 ref 来管理状态
const updateInfo = ref(null)
const hasUpdate = ref(false)
const hidB = ref(true)
const isDownloading = ref(false)
const showRestartDialog = ref(false)

// 在组件挂载后检查更新
onMounted(async () => {
  try {
    eventBus.on('downloadable', hiddenButton)
    const response = await checkUpdate()
    if (response.flag) {
      updateInfo.value = JSON.parse(response.resData)
      hasUpdate.value = response.flag
      if (response.resData == null) {
        hasUpdate.value = false
      }
    }
  } catch (error) {
    console.log('检查更新失败:', error)
  }
})

function hiddenButton() {
  hidB.value = false
}

function goChat() {
  emits('close')
  dialogRef.value.close()
}

async function handleRestart() {
  try {
    await exitImmediately()
  } catch (error) {
    console.error('重启应用失败:', error)
    toast.add({
      severity: 'error',
      summary: '重启失败',
      detail: '应用重启失败，请手动重启应用',
      life: 5000
    })
  }
  showRestartDialog.value = false
}

async function goChatWithUpdate() {
  emits('close')

  if (isDownloading.value) return

  try {
    isDownloading.value = true

    const response = await startDownload()
    emits('close')
    if (response.flag) {
      // ✅ 1. 解析 resData 中的 taskId
      const { task_id } = JSON.parse(response.resData)
      // ✅ 2. 通过 eventBus 通知 Main.vue
      eventBus.emit('start-update', { taskId: task_id })

      toast.add({
        severity: 'success',
        summary: '成功',
        detail: '开始下载...',
        life: 3000
      })
      dialogRef.value.close()
    } else {
      const errorMsg = response.msg || '更新包下载失败，请稍后重试'
      console.error('下载响应失败:', response)
      toast.add({
        severity: 'error',
        summary: '下载失败',
        detail: errorMsg,
        life: 5000
      })
      dialogRef.value.close()
    }
  } catch (error) {
    // 尝试完整提取所有信息
    const plainError = {
      message: error.message,
      code: error.code,
      name: error.name,
      stack: error.stack,
      isAxiosError: error.isAxiosError,
      config: error.config
    }

    const errorText = JSON.stringify(plainError, null, 2)

    console.error('❌ 下载错误对象:', errorText)

    // toast.add({
    //   severity: 'error',
    //   summary: '请求异常',
    //   detail: errorText,
    //   life: 0, // 永久保留直到关闭
    //   closable: true
    // })

    dialogRef.value.close()
  }
}
</script>

<template>
  <div class="whats-new-container">
    <div class="title">体验你的新版OpenChat！</div>

    <div class="features">
      <div class="feature-item">
        <i class="pi pi-desktop feature-icon"></i>
        <div class="text-container">
          <span> 支持多种AI模型接入方式 - DeepSeek、 Ollama、 云端大模型！</span>
          <span> — 已接入最新 “Qwen3” 语言大模型！！ </span>
        </div>
      </div>
      <div class="feature-item">
        <i class="pi pi-palette feature-icon"></i>
        <span>提供便捷的AI助手访问方式，满足你多种场景需求！</span>
      </div>
      <div class="feature-item">
        <i class="pi pi-box feature-icon"></i>
        <span>我们全力保障你的个人隐私，所有数据均本地存储！</span>
      </div>
    </div>

    <!-- 有更新时的显示 -->
    <template v-if="hasUpdate">
      <div class="update-card">
        <div class="update-header">
          <i class="pi pi-info-circle text-primary"></i>
          <span class="version-text">发现新版本：{{ updateInfo?.current_version }}</span>
        </div>
        <div class="update-content">
          <p class="update-time">更新时间：{{ updateInfo?.release_time }}</p>
          <pre class="release-log">{{ updateInfo?.release_log }}</pre>
        </div>
        <div class="button-group">
          <Button severity="success" label="立即更新" class="update-button" :disabled="hidB" @click="goChatWithUpdate"></Button>
          <Button severity="secondary" label="稍后再说" class="later-button" :disabled="isDownloading" @click="goChat"></Button>
        </div>
      </div>
    </template>

    <!-- 无更新时的显示 -->
    <template v-else>
      <Button severity="contrast" label="开始对话" class="start-button" @click="goChat"></Button>
    </template>

    <!-- 重启确认对话框 -->
    <Dialog
      v-model:visible="showRestartDialog"
      modal
      :closable="false"
      :pt="{
        root: { class: 'restart-dialog' }
      }"
    >
      <template #header>
        <div class="flex align-items-center gap-2">
          <i class="pi pi-check-circle text-success text-xl"></i>
          <span class="text-xl font-semibold">更新下载完成</span>
        </div>
      </template>
      <div class="update-success-content">
        <p>新版本已经下载完成，需要重启应用以完成更新。</p>
        <p class="text-sm text-500">建议立即重启以体验新功能。</p>
      </div>
      <template #footer>
        <div class="flex gap-2 justify-content-end">
          <!-- <Button label="稍后重启" severity="secondary" @click="showRestartDialog = false" /> -->
          <Button label="立即重启" severity="success" @click="handleRestart" />
        </div>
      </template>
    </Dialog>
  </div>
</template>

